public TvProgram(int code, int day, boolean isSport) {
    this.code = code;
    this.day = day;
    this.isSport = isSport;
}

public TvWeek() {
    arrProg = new TvProgram[100];
    current = 0;
}

public void addProgram(TvProgram p) {
    arrProg[current] = p;
    current++;
}

public int countSport() {
    int count = 0;
    for (int i = 0; i < current; i++) {
        if (arrProg[i].getIsSport()) {
            count++;
        }
    }
    return count;
}

